import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"謙","description":"周易集解 - 謙","frontmatter":{"title":"謙","description":"周易集解 - 謙"},"headers":[],"relativePath":"classics/jijie/015.md","filePath":"classics/jijie/015.md"}'),l={name:"classics/jijie/015.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="謙" tabindex="-1">謙 <a class="header-anchor" href="#謙" aria-label="Permalink to “謙”">​</a></h1><h2 id="謙-1" tabindex="-1">謙 <a class="header-anchor" href="#謙-1" aria-label="Permalink to “謙”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>謙，亨。君子有終。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：有大者不可以盈，故受之以謙。</p><p>崔憬曰：富貴而自遺其咎，故有大者不可盈。當須謙，天之道也。</p><p>虞翻曰：乾上九來之坤，與履旁通。天道下濟，故亨。</p><p>虞翻曰：君子謂三。艮終萬物，故｢君子有終｣。</p><p>鄭玄曰：艮為山，坤為地。山體高，今在地下，其於人道，高能下下，謙之象。亨者，嘉會之禮，以謙而為主。謙者，自貶損以下人，唯艮之堅固，坤之厚順，乃能終之，故君子之人有終也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：謙亨。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙，尊而光，卑而不可踰，君子之終也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>《九家易》曰：艮山，坤地。山至高，地至卑，以至高下至卑，故曰謙也。謙者兌世，艮與兌合，故亨。</p><p>荀爽曰：乾來之坤，故下濟。陰去為離，陽來成坎，日月之象，故光明也。</p><p>侯果曰：此本剝卦。乾之上九來居坤三，是天道下濟而光明也。坤之六三上升乾位，是地道卑而上行者也。</p><p>虞翻曰：謂乾盈履上，虧之坤三，故虧盈。貴處賤位，故益謙。</p><p>崔憬曰：若日中則昃，月滿則虧，損有餘以補不足，天之道也。</p><p>虞翻曰：謙二以坤變乾盈。坎動而潤下，水流濕，故流謙也。</p><p>崔憬曰：高岸為谷，深谷為陵，是為變盈而流謙，地之道也。</p><p>虞翻曰：鬼謂四。神謂三。坤為鬼害，乾為神福，故｢鬼神害盈而福謙｣也。</p><p>崔憬曰：朱門之家，鬼闞其室，黍稷非馨，明德惟馨，是其義矣。</p><p>虞翻曰：乾為好，為人。坤為惡也。故人道惡盈。從上之三，故好謙矣。</p><p>崔憬曰：滿招損，謙受益，人之道也。</p><p>虞翻曰：天道遠，故尊光。三位賤，故卑。坎水就下，險弱難勝，故不可踰。</p><p>孔穎達曰：尊者有謙，而更光明盛大。卑者有謙，而不踰越，是君子之終也。言君子能終其謙之善，而又獲謙之福，故曰君子有終也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：地中有山，謙。君子以裒多益寡，稱物平施。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>劉表曰：地中有山，以高下下，故曰謙。謙之為道，降已升人，山本地上，今居地中，亦降體之義，故為謙象也。</p><p>虞翻曰：君子謂三。裒，取也。艮為多；坤為寡；乾為物，為施；坎為平。謙乾盈益謙，故以裒多益寡，稱物平施。</p><p>侯果曰：裒，聚也。《彖》雲｢天道益謙｣，則謙之大者，天益之以大福；謙之小者，天益之以小福。故君子則之，以大益施大德，以小益施小德，是稱物平施也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，謙謙君子，用涉大川，吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>荀爽曰：初最在下，為謙。二陰承陽，亦為謙。故曰謙謙也。二陰一陽，相與成體，故曰君子也。九三體坎，故用涉大川吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：謙謙君子，卑以自牧也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：承陽卑謙，以陽自牧養也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，鳴謙，貞吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>姚信曰：三體震，為善鳴，二親承之，故曰鳴謙。得正處中，故貞吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鳴謙貞吉，中心得也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：言中正心與謙相得。</p><p>虞翻曰：中正謂二。坎為心也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，勞謙，君子有終，吉。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：體坎為勞，終下二陰，君子有終，故吉也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：勞謙君子，萬民服也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：陽光居五，自卑下眾，降居下體，君有下國之意也。眾陰皆欲撝陽上居五位，群陰順陽，故萬民服也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，無不利，撝謙。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>荀爽曰：四得位處正，家性為謙，故無不利。陰欲撝三，使上居五，故曰撝謙。撝，猶舉也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無不利撝謙，不違則也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：陰撝上陽，不違法則。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，不富以其鄰，利用侵伐，無不利。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>荀爽曰：鄰謂四與上也。自四以上乘陽，乘陽失實，故皆不富，五居中有體，故總言之。</p><p>荀爽曰：謂陽利侵伐來上，無敢不利之者。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利用侵伐，徵不服也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：不服，謂五也。</p><p>案：六五離爻。離為戈兵，侵伐之象也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，鳴謙，利用行師，徵邑國。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在震，故曰鳴謙。體師象，震為行，坤為邑國，利五之正，已得從徵，故｢利用行師，徵邑國｣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鳴謙，志未得也；可用行師，徵邑國也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：陰陽相應，故鳴謙也。雖應不承，故志未得。謂下九三可行師來上。坤為邑國也；三應上，上呼三徵，來居五位，故曰｢利用行師徵邑國｣也。</p><p>案：上六兌爻。兌為口舌，鳴謙之象也。</p>',84)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
